  "implementation": "def solve(case):
    segments = case['segments']
    budget = case['budget']

    # validate required fields and initialize
    n = len(segments)
    min_sum = 0
    cap_sum = 0
    allocations = []
    for s in segments:
        name = s['name']
        imp = s['importance']
        min_val = s['minimum']
        cap = s['capacity']
        min_sum += min_val
        cap_sum += cap
        allocations.append(min_val)

    if budget < min_sum or budget > cap_sum:
        raise ValueError('Budget out of range')

    remaining = budget - min_sum

    while remaining > 0:
        # find segment with best score, break ties by original order
        best_idx = -1
        best_score = -1.0
        for i, s in enumerate(segments):
            if allocations[i] < s['capacity']:
                score = s['importance'] / (allocations[i] + 1)
                if score > best_score:
                    best_score = score
                    best_idx = i
        if best_idx == -1:
            break  # all at capacity, should not happen if budget <= total capacity
        allocations[best_idx] += 1
        remaining -= 1

    by_name = {}
    for i, s in enumerate(segments):
        by_name[s['name']] = allocations[i]

    return {
        'allocations': allocations,
        'by_name': by_name,
        'total': sum(allocations)
    }"
}
